import {fmt} from './core.mjs';
export function concentrationColor(c,min=0,max=1){const f=Math.max(0,Math.min(1,(c-min)/(max-min||1))),a=[224,237,228],b=[130,70,122];return `rgb(${a.map((v,i)=>Math.round(v+(b[i]-v)*f)).join(',')})`;}
const gText=(x,y,t,extra='')=>`<text x="${x}" y="${y}" fill="#50655a" ${extra.includes('font-size=')?'':'font-size="11"'} ${extra}>${t}</text>`;
export function gradientDiagram(p,r){if(!r.valid)return '<svg viewBox="0 0 720 430" role="img" aria-label="Invalid design"><text x="360" y="180" text-anchor="middle" fill="#64776c">Correct the inputs to update the schematic.</text></svg>';
const low=p.type==='coflow'?Math.min(...p.concentrations):Math.min(p.ca,p.cb),high=p.type==='coflow'?Math.max(...p.concentrations):Math.max(p.ca,p.cb),col=c=>concentrationColor(c,low,high),stroke=Math.max(2,Math.min(12,(p.type==='coflow'?p.inletWidth:p.w)/70));let s='';
if(p.type==='tree'){
 const xy=id=>{const n=r.nodes[id];return {x:360+(n.j-(n.row+1)/2)*Math.min(83,540/(p.n-1)),y:45+n.row*210/(p.n-2||1)};};
 for(const e of r.edges){const a=xy(e.a),b=xy(e.b),pitch=[p.p1,p.p2,p.p3][r.nodes[e.a].row%3],pts=[a];for(let k=1;k<=pitch*2;k++){const f=k/(pitch*2+1);pts.push({x:a.x+(b.x-a.x)*f+(k%2?7:-7),y:a.y+(b.y-a.y)*f});}pts.push(b);const d=pts.map((v,i)=>`${i?'L':'M'}${v.x} ${v.y}`).join('');s+=`<path d="${d}" fill="none" stroke="#d4ded4" stroke-width="${stroke+3}" stroke-linejoin="round"/><path d="${d}" fill="none" stroke="${col(r.nodes[e.flow>=0?e.a:e.b].concentration)}" stroke-width="${stroke}" stroke-linejoin="round"><title>${fmt(e.flow*60e9,3)} µL/min (signed down the rows), ${fmt(e.length*1000,1)} mm</title></path>`;}
 for(const n of r.nodes){const a=xy(n.id);s+=`<circle cx="${a.x}" cy="${a.y}" r="${Math.max(4,stroke*.7)}" fill="${col(n.concentration)}" stroke="#fff"><title>${fmt(n.concentration,4)} mM, ${fmt(n.pressure/1000,4)} kPa</title></circle>`;}
 const a=xy(0),b=xy(1);s+=gText(a.x,24,`A · ${fmt(p.qa)} µL/min`,'text-anchor="end"')+gText(b.x,24,`B · ${fmt(p.qb)} µL/min`,'text-anchor="start"');
 for(const o of r.outlets){const a=xy(r.rows.at(-1)[o.index-1]),tail=10+Math.min(15,p.outLength);s+=`<path d="M${a.x} ${a.y}v${tail}" stroke="${col(o.c)}" stroke-width="${stroke}"><title>Outlet segment ${p.outLength} mm</title></path>`+gText(a.x,294,String(o.index),'text-anchor="middle"')+gText(a.x,311,fmt(o.c,3),'text-anchor="middle"');}
 s+=gText(25,330,`Row lengths = ${p.length} + ${p.pitchLength} × pitch count (mm); P = ${p.p1} / ${p.p2} / ${p.p3}, repeated.`,'font-size="10"');
}
if(p.type==='coflow'){
 const aw=520,ah=Math.max(72,Math.min(208,aw*p.chamberWidth/(p.chamberLength*1000))),x=115,y=75;
 for(let ix=0;ix<r.grid.length;ix+=2)for(let j=0;j<r.ny;j+=2)s+=`<rect x="${x+ix/r.grid.length*aw}" y="${y+j/r.ny*ah}" width="${Math.min(2,r.grid.length-ix)/r.grid.length*aw+.2}" height="${2/r.ny*ah+.2}" fill="${col(r.grid[ix][j])}"/>`;
 s+=`<rect x="${x}" y="${y}" width="${aw}" height="${ah}" fill="none" stroke="#8fa293"/>`;
 for(let i=0;i<6;i++){const yy=y+(r.bands[i]+r.bands[i+1])/2*ah;if(p.flows[i]>0)s+=`<path d="M40 ${yy}H${x}" stroke="${col(p.concentrations[i])}" stroke-width="${Math.max(1,Math.min(p.inletWidth*.035,(r.bands[i+1]-r.bands[i])*ah*.7))}"/>`;s+=gText(30,yy+3,String(i+1),'text-anchor="end"');}
 s+=gText(x,49,'6 inlets → flow-weighted bands → advection + diffusion')+gText(x+aw/2,y+ah+25,`${fmt(p.chamberLength)} mm · mean residence ${fmt(r.residence)} s`,'text-anchor="middle"')+gText(x+aw+8,y+ah/2,`${fmt(p.chamberWidth,0)} µm`,'font-size="10"')+gText(25,330,`Inlet width ${p.inletWidth} µm. Aspect ratio bounded for legibility; sampling bins are not physical outlets.`,'font-size="10"');
}
if(p.type==='bank'){
 s+=`<path d="M65 55H660" stroke="${col(p.ca)}" stroke-width="8"/><path d="M65 105H660" stroke="${col(p.cb)}" stroke-width="8"/>`+gText(25,59,'A')+gText(25,109,'B');
 for(const o of r.outlets){const xx=90+(o.index-1)*540/(p.n-1);for(const [len,from,off,c] of [[o.la,55,-9,p.ca],[o.lb,105,9,p.cb]])if(len!==null){const b=Math.min(6,Math.max(1,Math.ceil(len/20))),points=[`${xx+off},${from}`];for(let j=1;j<=b*2;j++)points.push(`${xx+off+(j%2?5:-5)},${from+(190-from)*j/(b*2+1)}`);points.push(`${xx},195`);s+=`<polyline points="${points.join(' ')}" fill="none" stroke="${col(c)}" stroke-width="${Math.min(7,stroke)}"/>`;}
 s+=`<path d="M${xx} 195V247" stroke="${col(o.c)}" stroke-width="${Math.min(12,stroke+2)}"/><circle cx="${xx}" cy="250" r="9" fill="${col(o.c)}"/>`+gText(xx,277,`${fmt(o.c,2)} mM`,'text-anchor="middle"')+gText(xx,299,`${o.la===null?'closed':fmt(o.la,1)} / ${o.lb===null?'closed':fmt(o.lb,1)}`,`text-anchor="middle" font-size="${p.n>8?7:9}"`);}
 s+=gText(25,330,'Feed lengths A / B (mm). Meanders indicate resistance; routing is illustrative, not a fabrication mask.','font-size="10"');
}
const sw=Math.min(120,(p.type==='coflow'?p.chamberWidth:p.w)*.13),sh=Math.max(2,Math.min(45,p.h*.2));s+=gText(25,359,`Channel ${p.type==='coflow'?p.chamberWidth:p.w} × ${p.h} µm; depth section at right.`,'font-size="10"')+`<rect x="540" y="342" width="${sw}" height="${sh}" fill="#e2ece2" stroke="#839786"/>`+gText(540+sw+6,354,`h ${p.h}`,'font-size="9"');s+=`<defs><linearGradient id="concentration-key"><stop stop-color="${col(low)}"/><stop offset="1" stop-color="${col(high)}"/></linearGradient></defs><rect x="25" y="391" width="140" height="6" rx="3" fill="url(#concentration-key)"/>`+gText(25,414,`${fmt(low,3)} mM`,'font-size="10"')+gText(165,414,`${fmt(high,3)} mM`,'text-anchor="end" font-size="10"')+gText(210,398,'Concentration color scale · lengths abbreviated','font-size="10"');return `<svg viewBox="0 0 720 430" role="img" aria-label="${p.type} gradient generator, ${p.n} outputs, parameter-linked dimensions and concentrations">${s}</svg>`;
}
